(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const $ = id => document.getElementById(id);
  const ui = {welcome:$('welcome'),hud:$('hud'),party:$('partyModal'),pause:$('pauseModal'),toast:$('toast'),hint:$('interactionHint'),hintText:$('hintText'),touch:$('touchControls'),chat:$('chatBar')};
  let W=0,H=0,dpr=1,playing=false,paused=false,room=null,channel=null,muted=false;
  const keys=new Set(), peers=new Map(), messages=[];
  const player={x:0,y:0,speed:165,health:100,warmth:100,wood:0,berries:0,day:1,time:0,xp:0};
  let objects=[], fires=[], toastTimer, lastFrame=0, hintTarget=null, joy={x:0,y:0}, startAt=0;
  const hash=(x,y)=>{let n=(x*374761393+y*668265263)|0;n=(n^(n>>>13))*1274126177;return ((n^(n>>>16))>>>0)/4294967295};
  const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
  function resize(){dpr=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);document.body.classList.toggle('mobile',W<700||('ontouchstart'in window));}
  addEventListener('resize',resize);resize();
  function toast(text){ui.toast.textContent=text;ui.toast.classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>ui.toast.classList.add('hidden'),2100)}
  function start(){if(playing)return;playing=true;paused=false;startAt=performance.now();ui.welcome.classList.add('dismissed');setTimeout(()=>ui.welcome.classList.add('hidden'),600);ui.hud.classList.remove('hidden');ui.touch.classList.remove('hidden');$('controlsNote').classList.remove('hidden');lastFrame=performance.now();toast('The forest is quiet. Follow the little trail north.');requestAnimationFrame(frame)}
  function newGame(){Object.assign(player,{x:0,y:0,health:100,warmth:100,wood:0,berries:0,day:1,time:0,xp:0});fires=[];objects=[];makeWorld();paused=false;ui.pause.classList.add('hidden');ui.welcome.classList.remove('hidden','dismissed');playing=false;start()}
  $('playBtn').onclick=start;
  $('partyBtn').onclick=()=>ui.party.classList.remove('hidden');
  $('createRoomBtn').onclick=()=>{room=new URLSearchParams(location.search).get('room')||Math.random().toString(36).slice(2,6).toUpperCase();$('roomCode').textContent=room;const u=new URL(location.href);u.searchParams.set('room',room);history.replaceState({},'',u);$('roomLabel').textContent='FOREST '+room;ui.party.classList.add('hidden');initRoom();toast('Your forest is ready. Invite a friend with the link!');start()};
  $('copyBtn').onclick=async()=>{try{await navigator.clipboard.writeText(location.href);$('copyBtn').textContent='Copied!';setTimeout(()=>$('copyBtn').textContent='Copy invite',1300)}catch(e){toast('Copy the invite link from your browser address bar.')}};
  $('menuBtn').onclick=()=>{if(playing&&!paused){paused=true;ui.pause.classList.remove('hidden')}};
  $('resumeBtn').onclick=()=>{paused=false;ui.pause.classList.add('hidden');lastFrame=performance.now();requestAnimationFrame(frame)};
  $('restartBtn').onclick=newGame;
  $('soundBtn').onclick=()=>{muted=!muted;$('soundBtn').textContent=muted?'♩':'♫';toast(muted?'Sound off':'Sound on')};
  document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('.modal').classList.add('hidden'));
  $('actionBtn').addEventListener('pointerdown',e=>{e.preventDefault();interact()});
  addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys.add(e.key.toLowerCase());if(e.repeat)return;if(e.key.toLowerCase()==='e')interact();if(e.key.toLowerCase()==='f')buildFire();if(e.key==='Escape'&&playing){paused=!paused;ui.pause.classList.toggle('hidden',!paused);if(!paused){lastFrame=performance.now();requestAnimationFrame(frame)}}if(e.key.toLowerCase()==='enter'&&ui.party.classList.contains('hidden')===false){ui.party.classList.add('hidden')}});
  addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
  const joyEl=$('joystick'),knob=$('joyKnob');let joyPointer=null;
  joyEl.addEventListener('pointerdown',e=>{joyPointer=e.pointerId;joyEl.setPointerCapture(joyPointer);moveJoy(e)});
  joyEl.addEventListener('pointermove',e=>{if(e.pointerId===joyPointer)moveJoy(e)});
  function moveJoy(e){const r=joyEl.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,dx=e.clientX-cx,dy=e.clientY-cy,len=Math.hypot(dx,dy),max=34,m=Math.min(max,len);joy.x=len?dx/len*m/max:0;joy.y=len?dy/len*m/max:0;knob.style.transform=`translate(${joy.x*m}px,${joy.y*m}px)`}
  function resetJoy(){joyPointer=null;joy.x=joy.y=0;knob.style.transform=''}joyEl.addEventListener('pointerup',resetJoy);joyEl.addEventListener('pointercancel',resetJoy);
  function makeWorld(){objects=[];for(let gy=-17;gy<18;gy++)for(let gx=-18;gx<19;gx++){let h=hash(gx,gy);if(h>.44){let x=gx*105+(hash(gx+55,gy)*70-35),y=gy*105+(hash(gx,gy+55)*70-35);const pathX=Math.sin(y/260)*110;if(Math.abs(x-pathX)<100)continue;let type=h>.96?'berries':(h>.78?'wood':'tree');objects.push({x,y,type,size: type==='tree'?34+hash(gx+4,gy+10)*22:12+hash(gx,gy)*4,seed:h,active:true})}}for(let i=0;i<34;i++){let y=-1150+i*70,x=Math.sin(y/260)*65+(hash(i,6)-.5)*35;objects.push({x,y,type:i%5===1?'berries':'wood',size:10,seed:hash(i,20),active:true})}}
  makeWorld();
  function initRoom(){if(channel)channel.close();channel=new BroadcastChannel('wildwood-'+room);channel.postMessage({type:'hello',id:PLAYER_ID,x:player.x,y:player.y,name:'Wanderer'});channel.onmessage=e=>{let m=e.data;if(m.id===PLAYER_ID)return;if(m.type==='hello'){peers.set(m.id,{...m,seen:Date.now()});channel.postMessage({type:'hello',id:PLAYER_ID,x:player.x,y:player.y,name:'Wanderer'});ui.chat.classList.remove('hidden')}else if(m.type==='move'){peers.set(m.id,{...m,seen:Date.now()});ui.chat.classList.remove('hidden')}else if(m.type==='leave')peers.delete(m.id);else if(m.type==='chat'){messages.push({id:m.id,text:m.text,until:Date.now()+4200});toast('A friend: '+m.text)}};addEventListener('beforeunload',()=>channel&&channel.postMessage({type:'leave',id:PLAYER_ID}));}
  const PLAYER_ID=Math.random().toString(36).slice(2);
  $('sendChat').onclick=sendChat;$('chatInput').addEventListener('keydown',e=>{if(e.key==='Enter')sendChat()});function sendChat(){let input=$('chatInput'),text=input.value.trim();if(!text)return;if(channel)channel.postMessage({type:'chat',id:PLAYER_ID,text});toast('You: '+text);input.value=''}
  function screen(x,y){return {x:W/2+(x-player.x),y:H*.55+(y-player.y)}}
  function interact(){if(!playing){start();return}let nearest=null,dist=62;for(const o of objects){if(!o.active||o.type==='tree')continue;let d=Math.hypot(o.x-player.x,o.y-player.y);if(d<dist){dist=d;nearest=o}}if(nearest){nearest.active=false;if(nearest.type==='wood'){player.wood++;toast('Picked up a fallen branch. ('+player.wood+' wood)')}else{player.berries++;player.health=Math.min(100,player.health+9);toast('Wild berries! A little strength restored.')}updateHUD();return}for(let f of fires)if(Math.hypot(f.x-player.x,f.y-player.y)<80){player.warmth=Math.min(100,player.warmth+28);player.health=Math.min(100,player.health+5);toast('You warm your hands by the fire.');updateHUD();return}if(Math.hypot(player.x,player.y+1150)<90){win();return}toast('Nothing close by to gather. Look for little golden glimmers.')}
  function buildFire(){if(!playing)return;if(player.wood<3){toast('Gather 3 branches to build a campfire.');return}player.wood-=3;fires.push({x:player.x,y:player.y,age:0});player.warmth=Math.min(100,player.warmth+35);toast('A little fire, just when you needed it.');updateHUD()}
  function win(){paused=true;toast('You found the way home. The woods will remember you.');setTimeout(()=>{ui.pause.classList.remove('hidden');ui.pause.querySelector('.eyebrow').textContent='YOU MADE IT HOME';ui.pause.querySelector('h2').textContent='The trail ends here.';ui.pause.querySelector('p').textContent='You gathered '+player.wood+' branches and '+player.berries+' handfuls of berries along the way.'},800)}
  function updateHUD(){ $('woodCount').textContent=player.wood;$('berryCount').textContent=player.berries;$('healthValue').textContent=Math.round(player.health);$('warmthValue').textContent=Math.round(player.warmth);$('healthFill').style.width=player.health+'%';$('warmthFill').style.width=player.warmth+'%';let pct=(player.time%90)/90;$('dayProgress').style.width=(pct*100)+'%';const night=pct>.72||pct<.14;$('timePhase').textContent=night?'DUSK':'MORNING';$('timeIcon').textContent=night?'☾':'☼';$('dayLabel').textContent='DAY '+player.day;let goal=Math.hypot(player.x,player.y+1150);$('objective').textContent=goal<90?'You found the trail home!':(player.wood<3?'Gather 3 branches for warmth':'Follow the trail home');}
  function frame(now){if(!playing||paused)return;let dt=Math.min(.04,(now-lastFrame)/1000||0);lastFrame=now;update(dt);draw(now/1000);requestAnimationFrame(frame)}
  function update(dt){let dx=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0)+joy.x,dy=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0)+joy.y,len=Math.hypot(dx,dy);if(len>1){dx/=len;dy/=len}let running=keys.has('shift')&&player.warmth>8;player.x+=dx*player.speed*(running?1.55:1)*dt;player.y+=dy*player.speed*(running?1.55:1)*dt;player.time+=dt;if(player.time>=90){player.time=0;player.day++}const night=player.time>66||player.time<12,nearFire=fires.some(f=>Math.hypot(f.x-player.x,f.y-player.y)<150);player.warmth=clamp(player.warmth+(nearFire?13:(night?-2.8:-.42))*dt,0,100);if(player.warmth<20)player.health=clamp(player.health-1.6*dt,0,100);else player.health=clamp(player.health+.15*dt,0,100);if(player.health<=0){player.health=55;player.warmth=48;player.x=0;player.y=0;toast('A kind forest spirit helped you back to the trail.')}for(const f of fires)f.age+=dt;fires=fires.filter(f=>f.age<90);let nearest=Infinity;hintTarget=null;for(let o of objects)if(o.active&&o.type!=='tree'){let d=Math.hypot(o.x-player.x,o.y-player.y);if(d<nearest){nearest=d;hintTarget=o}}if(nearest<68){ui.hintText.textContent=hintTarget.type==='wood'?'Gather branch':'Pick wild berries';ui.hint.classList.remove('hidden')}else if(fires.some(f=>Math.hypot(f.x-player.x,f.y-player.y)<75)){ui.hintText.textContent='Warm by the fire';ui.hint.classList.remove('hidden')}else ui.hint.classList.add('hidden');updateHUD();if(channel&&Math.random()<dt*2)channel.postMessage({type:'move',id:PLAYER_ID,x:player.x,y:player.y,name:'Wanderer'});for(let [id,p] of peers)if(Date.now()-p.seen>12000)peers.delete(id);}
  function draw(t){ctx.clearRect(0,0,W,H);const sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#1a2a20');sky.addColorStop(.52,'#304633');sky.addColorStop(1,'#17271c');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);const night=player.time>66||player.time<12;ctx.fillStyle=night?'rgba(13,23,36,.36)':'rgba(218,180,111,.04)';ctx.fillRect(0,0,W,H);
    // dappled moss floor and distant trunks
    for(let i=0;i<75;i++){let wx=(hash(i,71)*2-1)*W*1.5,wy=(hash(i,72)*2-1)*H*1.7;let p=screen(wx,wy);if(p.x< -80||p.x>W+80||p.y< -80||p.y>H+80)continue;ctx.fillStyle=`rgba(${i%3===0?'118,137,81':'24,49,32'},${.08+hash(i,75)*.12})`;ctx.beginPath();ctx.ellipse(p.x,p.y,25+hash(i,76)*42,10+hash(i,77)*24,0,0,Math.PI*2);ctx.fill()}
    drawPath();for(const o of objects){if(!o.active)continue;let p=screen(o.x,o.y);if(p.x< -90||p.x>W+90||p.y< -100||p.y>H+100)continue;if(o.type==='tree')drawTree(p.x,p.y,o.size,o.seed);else drawCollectible(p.x,p.y,o.type,o.seed)}
    for(const f of fires)drawFire(screen(f.x,f.y),t);
    drawHome();for(const p of peers.values()){let s=screen(p.x,p.y);if(s.x>-40&&s.x<W+40&&s.y>-40&&s.y<H+40)drawPeer(s.x,s.y,t)}drawPlayer(W/2,H*.55,t);drawFireflies(t);
    if(!playing){ctx.fillStyle='rgba(8,18,13,.08)';ctx.fillRect(0,0,W,H)}
  }
  function drawPath(){ctx.save();ctx.lineCap='round';ctx.lineJoin='round';for(let layer=0;layer<3;layer++){ctx.beginPath();for(let i=0;i<=30;i++){let wy=player.y-800+i*70,p=screen(Math.sin(wy/260)*65+(layer-1)*28,wy);if(i===0)ctx.moveTo(p.x,p.y);else ctx.lineTo(p.x,p.y)}ctx.strokeStyle=layer===1?'rgba(183,153,102,.24)':'rgba(166,148,106,.11)';ctx.lineWidth=layer===1?52:78;ctx.stroke()}for(let i=0;i<28;i++){let wy=player.y-800+i*78,wx=Math.sin(wy/260)*65+(hash(i,4)-.5)*38,p=screen(wx,wy);ctx.fillStyle='rgba(212,189,136,.17)';ctx.beginPath();ctx.ellipse(p.x,p.y,2+hash(i,8)*3,1.3,0,0,Math.PI*2);ctx.fill()}ctx.restore()}
  function drawTree(x,y,s,seed){let depth=clamp((y/H+.4),.45,1.3),r=s*depth;ctx.save();ctx.fillStyle='rgba(4,12,8,.28)';ctx.beginPath();ctx.ellipse(x+8*depth,y+8*depth,r*.9,r*.38,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=seed>.88?'#332b20':'#392f23';ctx.fillRect(x-r*.16,y-r*.28,r*.32,r*.77);let colors=seed>.88?['#405440','#344934','#2a402f']:['#284531','#203c2c','#193626'];for(let j=0;j<3;j++){let rr=r*(1-j*.19);ctx.fillStyle=colors[j];ctx.beginPath();ctx.moveTo(x,y-r*(1.9-j*.42));ctx.bezierCurveTo(x-rr*1.2,y-r*.88,x-rr*1.45,y-r*.15,x,y+r*.07);ctx.bezierCurveTo(x+rr*1.45,y-r*.15,x+rr*1.2,y-r*.88,x,y-r*(1.9-j*.42));ctx.fill()}ctx.fillStyle='rgba(170,178,113,.12)';ctx.beginPath();ctx.ellipse(x-r*.28,y-r*.75,r*.23,r*.52,-.4,0,Math.PI*2);ctx.fill();ctx.restore()}
  function drawCollectible(x,y,type,s){ctx.save();ctx.fillStyle='rgba(0,0,0,.24)';ctx.beginPath();ctx.ellipse(x,y+5,9,4,0,0,Math.PI*2);ctx.fill();if(type==='wood'){ctx.rotate(s*5);ctx.strokeStyle='#c19c68';ctx.lineWidth=5;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(x-7,y+2);ctx.lineTo(x+6,y-3);ctx.stroke();ctx.strokeStyle='#e2c48e';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x-6,y+1);ctx.lineTo(x+5,y-4);ctx.stroke()}else{ctx.fillStyle='rgba(224,190,115,.14)';ctx.beginPath();ctx.arc(x,y,15+Math.sin(performance.now()/400+s)*2,0,Math.PI*2);ctx.fill();for(let i=0;i<3;i++){ctx.fillStyle=['#a95357','#c16b57','#a65d67'][i];ctx.beginPath();ctx.arc(x+(i-1)*5,y+Math.cos(i)*3,3.2,0,Math.PI*2);ctx.fill()}ctx.fillStyle='#87a66e';ctx.fillRect(x-1,y-7,2,4)}ctx.restore()}
  function drawPlayer(x,y,t){ctx.save();ctx.fillStyle='rgba(2,10,7,.35)';ctx.beginPath();ctx.ellipse(x,y+17,14,7,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d2a978';ctx.beginPath();ctx.arc(x,y-5,6.2,0,Math.PI*2);ctx.fill();ctx.fillStyle='#b9c9ad';ctx.beginPath();ctx.ellipse(x,y+6,8,11,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#8b5844';ctx.beginPath();ctx.arc(x,y-8,6,Math.PI,0);ctx.fill();ctx.fillStyle='#e7d8b8';ctx.fillRect(x-2,y+12,4,5);if(Math.hypot(joy.x,joy.y)>.1||keys.size) {ctx.strokeStyle='#d2a978';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x-6,y+5);ctx.lineTo(x-11,y+10+Math.sin(t*10)*2);ctx.moveTo(x+6,y+5);ctx.lineTo(x+11,y+10-Math.sin(t*10)*2);ctx.stroke()}ctx.restore()}
  function drawFire(s,t){ctx.save();ctx.fillStyle='rgba(242,162,79,.16)';ctx.beginPath();ctx.arc(s.x,s.y,39+Math.sin(t*4)*4,0,Math.PI*2);ctx.fill();ctx.fillStyle='#65472d';ctx.lineWidth=4;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(s.x-8,s.y+8);ctx.lineTo(s.x+8,s.y+13);ctx.moveTo(s.x+8,s.y+8);ctx.lineTo(s.x-8,s.y+13);ctx.stroke();ctx.fillStyle='#f9b851';ctx.beginPath();ctx.moveTo(s.x,s.y+9);ctx.bezierCurveTo(s.x-12,s.y-4,s.x+3,s.y-15+Math.sin(t*9)*3,s.x+2,s.y-19);ctx.bezierCurveTo(s.x+18,s.y-2,s.x+12,s.y+5,s.x,s.y+9);ctx.fill();ctx.fillStyle='#fff0bb';ctx.beginPath();ctx.arc(s.x+2,s.y+1,3,0,Math.PI*2);ctx.fill();ctx.restore()}
  function drawHome(){let p=screen(0,-1150);if(p.y< -100||p.y>H+100)return;ctx.save();ctx.fillStyle='rgba(237,196,126,.13)';ctx.beginPath();ctx.arc(p.x,p.y,54,0,Math.PI*2);ctx.fill();ctx.strokeStyle='rgba(232,198,135,.8)';ctx.setLineDash([3,5]);ctx.beginPath();ctx.arc(p.x,p.y,30,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);ctx.font='10px DM Mono,monospace';ctx.textAlign='center';ctx.fillStyle='#f1d8a5';ctx.fillText('HOME',p.x,p.y-40);ctx.fillStyle='#473728';ctx.fillRect(p.x-20,p.y-9,40,26);ctx.fillStyle='#815a3d';ctx.beginPath();ctx.moveTo(p.x-25,p.y-9);ctx.lineTo(p.x,p.y-28);ctx.lineTo(p.x+25,p.y-9);ctx.fill();ctx.fillStyle='#efc77d';ctx.fillRect(p.x-4,p.y+5,8,12);ctx.restore()}
  function drawPeer(x,y,t){ctx.save();ctx.fillStyle='rgba(247,207,130,.18)';ctx.beginPath();ctx.arc(x,y,20+Math.sin(t*3)*2,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f5d28e';ctx.beginPath();ctx.arc(x,y-3,4,0,Math.PI*2);ctx.fill();ctx.fillStyle='#bfd2af';ctx.beginPath();ctx.ellipse(x,y+6,6,8,0,0,Math.PI*2);ctx.fill();ctx.font='9px DM Sans';ctx.textAlign='center';ctx.fillStyle='#f2e7ca';ctx.fillText('friend',x,y-16);ctx.restore()}
  function drawFireflies(t){for(let i=0;i<19;i++){let wx=(hash(i,8)*2-1)*W*.75,wy=(hash(i,9)*2-1)*H,p=screen(wx,wy);let a=.25+.55*(.5+.5*Math.sin(t*2+i*4));ctx.fillStyle=`rgba(237,211,137,${a})`;ctx.beginPath();ctx.arc(p.x+Math.sin(t+i)*4,p.y+Math.cos(t*1.3+i)*3,1.4,0,Math.PI*2);ctx.fill()}}
  if(new URLSearchParams(location.search).has('room')){$('roomLabel').textContent='FOREST '+new URLSearchParams(location.search).get('room').toUpperCase();room=new URLSearchParams(location.search).get('room').toUpperCase();$('partyBtn').innerHTML='<span class="people-icon">♧</span> Join this forest';$('partyBtn').onclick=()=>{initRoom();ui.party.classList.add('hidden');start();toast('You joined a friend’s forest.')}}
  // Render the forest behind the welcome screen before the first adventure.
  draw(0);
})();

